func UpperFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	if r == utf8.RuneError && size <= 1 {
		return s // already invalid: do not compound it
	}
	return string(unicode.ToUpper(r)) + s[size:]
}

// invalidUTF8Window — referenced by InvalidUTF8At and omitted from round 2's
// sketch (editquality LOW). ±48 bytes: wide enough to recognise the text, short
// enough to log.
const invalidUTF8Window = 48

func InvalidUTF8At(s string) (offset int, window string, found bool) {
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size <= 1 {
			lo, hi := i-invalidUTF8Window, i+invalidUTF8Window
			if lo < 0 { lo = 0 }
			if hi > len(s) { hi = len(s) }
			return i, strconv.QuoteToASCII(s[lo:hi]), true
		}
		i += size
	}
	return 0, "", false
}

